/**
 * Offers the workspace to another active member. Only the recorded owner
 * (`organization.ownerId`) may do this — holding the owner role is not enough —
 * and only one offer may be open at a time.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === actor.userId) throw new OwnershipHandoverError("self");

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  if ((await findOpenHandover(orgId, now)) !== null) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const handover = await handoverRepo.insertHandover({
    orgId,
    fromUserId: actor.userId,
    toUserId,
    createdAt: toIsoTimestamp(now),
    expiresAt: toIsoTimestamp(new Date(now.getTime() + HANDOVER_TTL_MS)),
  });

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You have been offered ownership of this workspace",
    body: `${org.name} ownership was offered to you by ${actor.userId}`,
    href: "/settings",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offered member takes the workspace over. The new owner is promoted
 * before the previous one steps down, so the org has an owner throughout.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const handover = await requireActionableHandover(actor, orgId);
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);

  const incoming = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );
  if (incoming.role !== "owner") {
    await changeRole(actor, incoming, "owner");
  }

  await orgRepo.updateOrgOwner(orgId, actor.userId);

  const previousOwnerId = org.ownerId;
  if (previousOwnerId !== actor.userId) {
    const outgoing = await memberRepo.findMember(orgId, previousOwnerId);
    if (outgoing && outgoing.role === "owner") {
      await assertLastOwnerRetained(orgId, outgoing.id, "admin");
      await changeRole(actor, outgoing, "admin");
    }
  }

  await handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "accepted",
    toIsoTimestamp(new Date()),
  );

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: previousOwnerId,
    toUserId: actor.userId,
  });

  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const handover = await requireActionableHandover(actor, orgId);
  return handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
}

/** The recorded owner withdraws the open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  const now = new Date();
  const handover = await findOpenHandover(orgId, now);
  if (handover === null) throw new OwnershipHandoverError("nothing_pending");

  return handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "canceled",
    toIsoTimestamp(now),
  );
}

/** The open offer, if any; a lapsed offer is not open. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  return findOpenHandover(orgId, new Date());
}

function isLapsed(handover: OwnershipHandover, now: Date): boolean {
  return now.getTime() >= Date.parse(handover.expiresAt);
}

async function findOpenHandover(
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover | null> {
  const pending = await handoverRepo.findPendingHandover(orgId);
  return pending !== null && !isLapsed(pending, now) ? pending : null;
}

/** The pending offer addressed to `actor`, refusing when absent or lapsed. */
async function requireActionableHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  const pending = await handoverRepo.findPendingHandover(orgId);
  if (pending === null || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (isLapsed(pending, new Date())) {
    throw new OwnershipHandoverError("expired");
  }
  return pending;
}

/** Offering and withdrawing belong to the recorded owner, not to the role. */
function assertRecordedOwner(actor: Actor, org: Organization): void {
  if (org.ownerId === actor.userId) return;

  throw new PermissionDeniedError("org:manage_billing", {
    allowed: false,
    action: "org:manage_billing",
    resourceKind: "organization",
    reason: "denied_by_role",
  });
}

/** A role change made by the handover, announced like a manual one. */
async function changeRole(
  actor: Actor,
  member: Member,
