import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
import { registerEventHandlers } from "@/server/services/event-registry";
import * as org from "@/server/services/organization-service";
import * as memberService from "@/server/services/member-service";
import * as memberRepo from "@/server/repositories/member-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import { OwnershipHandoverError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());
it("flows", async () => {
  const t = await createTenant("ho", "growth");
  await expect(org.initiateOwnershipHandover(t.actors.admin, t.org.id, t.userIds.member)).rejects.toBeInstanceOf(PermissionDeniedError);
  await expect(org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.owner)).rejects.toMatchObject({ reason: "self" });
  const h = await org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.viewer);
  expect(Date.parse(h.expiresAt) - Date.parse(h.createdAt)).toBe(7*86400000);
  await expect(org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member)).rejects.toMatchObject({ reason: "pending_exists" });
  expect((await org.getPendingOwnershipHandover(t.actors.member, t.org.id))?.toUserId).toBe(t.userIds.viewer);
  await expect(org.acceptOwnershipHandover(t.actors.member, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
  const updated = await org.acceptOwnershipHandover(t.actors.viewer, t.org.id);
  expect(updated.ownerId).toBe(t.userIds.viewer);
  expect((await memberRepo.findMember(t.org.id, t.userIds.owner))?.role).toBe("admin");
  expect((await memberRepo.findMember(t.org.id, t.userIds.viewer))?.role).toBe("owner");
  const acts = await activityRepo.listActivity({ orgId: t.org.id, limit: 50, cursor: null } as never);
  console.log(acts.items.map(a => [a.action, JSON.stringify(a.metadata)]));
  await expect(org.acceptOwnershipHandover(t.actors.viewer, t.org.id)).rejects.toBeInstanceOf(OwnershipHandoverError);
  const newOwner = { ...t.actors.viewer, role: "owner" as const };
  const prev = (await memberRepo.findMember(t.org.id, t.userIds.owner))!;
  await memberService.removeMember(newOwner, { orgId: t.org.id, memberId: prev.id });
  await org.initiateOwnershipHandover(newOwner, t.org.id, t.userIds.member);
  const m = (await memberRepo.findMember(t.org.id, t.userIds.member))!;
  await memberService.removeMember(newOwner, { orgId: t.org.id, memberId: m.id });
  expect(await org.getPendingOwnershipHandover(newOwner, t.org.id)).toBeNull();
  vi.useFakeTimers();
  vi.setSystemTime(new Date("2030-01-01T00:00:00Z"));
  await org.initiateOwnershipHandover(newOwner, t.org.id, t.userIds.admin);
  vi.setSystemTime(new Date("2030-01-08T00:00:00Z"));
  await expect(org.acceptOwnershipHandover(t.actors.admin, t.org.id)).rejects.toMatchObject({ reason: "expired" });
  expect(await org.getPendingOwnershipHandover(newOwner, t.org.id)).toBeNull();
  vi.useRealTimers();
});
